// Synthetic filesystem and injected failure tests. Never attaches to Siemens.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using System.Web.Script.Serialization;

internal static class LabNewModulesTests
{
    private static Type lab;
    private static string root, exports, package;
    private static JavaScriptSerializer json = new JavaScriptSerializer();
    private static List<object> results = new List<object>();
    private static object Call(string name, params object[] args)
    {
        try { return lab.GetMethod(name, BindingFlags.NonPublic | BindingFlags.Static).Invoke(null, args); }
        catch (TargetInvocationException ex) { throw ex.InnerException; }
    }
    private static string New(string parent) { string p = Path.Combine(parent, Guid.NewGuid().ToString("N")); Directory.CreateDirectory(p); return p; }
    private static void Check(bool value) { if (!value) throw new Exception("assertion failed"); }
    private static void Reject(Action action, string code)
    {
        try { action(); } catch (Exception ex) { if (ex.Message.Contains(code)) return; throw; }
        throw new Exception("expected refusal: " + code);
    }
    private static void Test(string name, Action body)
    {
        var previous = Console.Error;
        var diagnostics = new StringWriter();
        Console.SetError(diagnostics);
        try { body(); results.Add(new { name, status = "PASS", diagnostics = diagnostics.ToString() }); Console.WriteLine("PASS " + name); }
        catch (Exception ex) { results.Add(new { name, status = "FAIL", error = ex.ToString(), diagnostics = diagnostics.ToString() }); Console.WriteLine("FAIL " + name + ": " + ex); }
        finally { Console.SetError(previous); }
    }
    private static string Hash(string file)
    { using (var sha = SHA256.Create()) return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(file))).Replace("-", "").ToLowerInvariant(); }
    private static void Write(string file, string value) { File.WriteAllText(file, value, new UTF8Encoding(false)); }
    private static string Clone(string source) { string dest = New(root); Call("CopyDirectory", source, dest); return dest; }
    private static void CopyPair(string source, string destination)
    { foreach (string ext in new[] { ".hmi.js", ".hmi.yml" }) File.Copy(Path.Combine(source, "Synthetic" + ext), Path.Combine(destination, "Synthetic" + ext)); }
    private static string Pair(string js = "old", string yml = "metadata")
    { string p = New(root); Write(Path.Combine(p, "Synthetic.hmi.js"), js); Write(Path.Combine(p, "Synthetic.hmi.yml"), yml); return p; }
    private static Dictionary<string, object> Expected(string pair)
    { return new Dictionary<string, object> { { "baseline_js_sha256", Hash(Path.Combine(pair, "Synthetic.hmi.js")) }, { "baseline_yml_sha256", Hash(Path.Combine(pair, "Synthetic.hmi.yml")) } }; }
    private static string Prepare(string source)
    { string p = New(root); Call("PrepareForceImportInput", source, p); return p; }
    private const string Marker = "/*<auto-generated>\r\n***End of Global definition area***\r\nChanges to this comment may cause incorrect behavior during document based import.\r\n</auto-generated>*/\r\n";
    private static string AddModule(string input, string name = "NewModule")
    {
        string dir = Path.Combine(input, name); Directory.CreateDirectory(dir);
        Write(Path.Combine(dir, "_Global_definition_area.js"), "const label = \"" + (char)0x17c + "\";\r\n" + Marker);
        Write(Path.Combine(dir, "alpha.js"), "export async function alpha(value, screen) { return value; }\r\n");
        return dir;
    }
    private static string CreatePackage() { string input = Clone(package); AddModule(input); return input; }
    private static string PrepareCreates(string input) { string p = New(root); Call("PrepareForceImportInputCore", input, p, true); return p; }
    private static Dictionary<string, object> Manifest(string prepared)
    { return (Dictionary<string, object>)json.DeserializeObject(File.ReadAllText(Path.Combine(prepared, "input-manifest.json"))); }
    private static Dictionary<string, object> Created(string prepared)
    { return ((object[])Manifest(prepared)["modules"]).Cast<Dictionary<string, object>>().Single(m => (string)m["module_name"] == "NewModule"); }
    private static object Plan(string[] updates, string[] creates, string[] actual, bool enabled = true)
    { return Call("PlanModuleChanges", updates, creates, actual, enabled); }
    private static string MultiReadback(string prepared)
    {
        string result = New(exports); var modules = new List<object>();
        foreach (Dictionary<string, object> module in (object[])Manifest(prepared)["modules"])
        {
            string name = (string)module["module_name"], native = Path.Combine(result, name, ".native"); Directory.CreateDirectory(native);
            foreach (string ext in new[] { ".hmi.js", ".hmi.yml" }) File.Copy(Path.Combine(prepared, name + ext), Path.Combine(native, name + ext));
            modules.Add(new { name, native_files = Directory.GetFiles(native).Select(f => new { name = Path.GetFileName(f), sha256 = Hash(f), length = new FileInfo(f).Length }).ToArray() });
        }
        Write(Path.Combine(result, "force-import-readback.json"), json.Serialize(new { status = "PASS_EXACT_MODULE_SET_AND_READBACK", saved = true,
            import_returned = true, is_modified_after = false, compile = new { state = "Success", error_count = 0, warning_count = 0, messages = new object[0] }, modules }));
        return result;
    }
    private static int Main(string[] args)
    {
        root = args[0]; exports = args[1]; package = args[2];
        AppDomain.CurrentDomain.AssemblyResolve += (sender, e) => {
            string name = new AssemblyName(e.Name).Name + ".dll";
            foreach (string dir in new[] { @"C:\Program Files\Siemens\Automation\Portal V19\PublicAPI\V19", @"C:\Program Files\Siemens\Automation\Portal V19\Bin\PublicAPI" })
                if (File.Exists(Path.Combine(dir, name))) return Assembly.LoadFrom(Path.Combine(dir, name));
            return null;
        };
        lab = Assembly.LoadFrom(args[3]).GetType("LabExporter", true);
        Test("opt-in assembles Unicode async source and keeps native history absent", () => {
            string input = CreatePackage(), snapshot = Clone(input), prepared = PrepareCreates(input); var m = Created(prepared);
            Check((string)m["action"] == "CREATE" && m["baseline_js_sha256"] == null && m["baseline_yml_sha256"] == null);
            Check(Convert.ToInt32(m["function_count"]) == 1 && Convert.ToInt32(Manifest(prepared)["module_count"]) == 2);
            Check(File.ReadAllText(Path.Combine(prepared,"NewModule.hmi.js")) == File.ReadAllText(Path.Combine(input,"NewModule","_Global_definition_area.js")) + File.ReadAllText(Path.Combine(input,"NewModule","alpha.js")));
            Check(File.ReadAllText(Path.Combine(prepared,"NewModule.hmi.yml")) == "#Version: 2.0\r\n\r\nScriptModules:\r\n  NewModule:\r\n    ScriptFile: NewModule.hmi.js\r\n");
            Call("VerifyWorkspaceSnapshot", input, snapshot); Check(!Directory.Exists(Path.Combine(input,"NewModule",".native")));
        });
        Test("default strict preparation retains root-set refusal with diagnostic", () => Reject(() => Prepare(CreatePackage()), "SCRIPTS_ROOT_CONTENT_SET_INVALID"));
        Test("new modules do not relax existing native validation", () => {
            string input = CreatePackage(); Directory.Move(Path.Combine(input,"Synthetic",".native"), Path.Combine(New(root),"preserved-native"));
            Reject(() => PrepareCreates(input), "MODULE_NATIVE_MANIFEST_MISSING");
        });
        foreach (string entry in new[] { "notes.txt", "module.json", ".native", "nested" })
        {
            string bad = entry;
            Test("undeclared content rejected " + bad, () => {
                string input = CreatePackage(), path = Path.Combine(input,"NewModule",bad);
                if (bad.StartsWith(".") || bad == "nested") Directory.CreateDirectory(path); else Write(path,"extra");
                Reject(() => PrepareCreates(input), "NEW_MODULE_CONTENT_SET_INVALID");
            });
        }
        Test("root extra file is never treated as a new module", () => { string input = Clone(package); Write(Path.Combine(input,"note.txt"),"x"); Reject(() => PrepareCreates(input), "SCRIPTS_ROOT_CONTENT_SET_INVALID"); });
        Test("unsupported YAML scalar module name refused", () => { string input = Clone(package); AddModule(input,"Bad#Name"); Reject(() => PrepareCreates(input), "NEW_MODULE_NAME_UNSUPPORTED"); });
        Test("missing global prefix refused", () => { string input=CreatePackage(); File.Delete(Path.Combine(input,"NewModule","_Global_definition_area.js")); Reject(() => PrepareCreates(input), "NEW_MODULE_CONTENT_SET_INVALID"); });
        foreach (string global in new[] { "const x=1;", Marker + Marker, "export function hidden(){}\r\n" + Marker, Marker + "const after=1;" })
        {
            string prefix = global;
            Test("invalid global prefix rejected " + results.Count, () => { string input=CreatePackage(); Write(Path.Combine(input,"NewModule","_Global_definition_area.js"),prefix); Reject(() => PrepareCreates(input), "NEW_MODULE_"); });
        }
        foreach (string code in new[] { "export function alpha( {", "function alpha() {}", "export default function alpha() {}", "export const alpha=()=>1;", "export function other() {}", "export function* alpha() {}", "export function alpha(...args) {}", "export function alpha(x=1) {}", "export function alpha() {} export function beta() {}" })
        {
            string function = code;
            Test("unsupported function refused " + results.Count, () => { string input=CreatePackage(); Write(Path.Combine(input,"NewModule","alpha.js"),function); Reject(() => PrepareCreates(input), "NEW_MODULE_SYNTAX_INVALID"); });
        }
        Test("top-level JS is parsed but never executed", () => { string input=CreatePackage(); Write(Path.Combine(input,"NewModule","_Global_definition_area.js"), "throw new Error('UNTRUSTED_SCRIPT_WAS_EXECUTED');\r\n"+Marker); PrepareCreates(input); });
        Test("invalid UTF8 refused", () => { string input=CreatePackage(); File.WriteAllBytes(Path.Combine(input,"NewModule","alpha.js"), new byte[]{0xff}); Reject(() => PrepareCreates(input), "NEW_MODULE_SOURCE_ENCODING_INVALID"); });
        Test("source size limit enforced before parsing", () => { string input=CreatePackage(); Write(Path.Combine(input,"NewModule","alpha.js"), new string(' ',1024*1024+1)); Reject(() => PrepareCreates(input), "NEW_MODULE_SOURCE_SIZE_LIMIT"); });
        Test("aggregate source size limit enforced during assembly", () => { string input=CreatePackage(); Write(Path.Combine(input,"NewModule","alpha.js"), new string(' ',600000)); Write(Path.Combine(input,"NewModule","beta.js"), new string(' ',600000)); Reject(() => PrepareCreates(input), "NEW_MODULE_SOURCE_SIZE_LIMIT"); });
        Test("UTF8 BOM and mixed line endings preserved byte exactly", () => { string input=CreatePackage(), prefix=Path.Combine(input,"NewModule","_Global_definition_area.js"), function=Path.Combine(input,"NewModule","alpha.js"); Write(prefix,"\ufeff"+File.ReadAllText(prefix)); Write(function,File.ReadAllText(function).Replace("\r\n","\n")); string prepared=PrepareCreates(input); Check(File.ReadAllBytes(Path.Combine(prepared,"NewModule.hmi.js")).SequenceEqual(File.ReadAllBytes(prefix).Concat(File.ReadAllBytes(function)))); });
        Test("source-file comment swallowing next export refused", () => { string input=CreatePackage(); Write(Path.Combine(input,"NewModule","alpha.js"),"export function alpha() {} //no newline"); Write(Path.Combine(input,"NewModule","beta.js"),"export function beta() {}\r\n"); Reject(() => PrepareCreates(input), "NEW_MODULE_SYNTAX_INVALID"); });
        Test("function assembly uses ordinal order", () => { string input=CreatePackage(); Write(Path.Combine(input,"NewModule","Zeta.js"),"export function Zeta() {}\r\n"); string prepared=PrepareCreates(input); Check(((object[])Created(prepared)["function_names"]).Select(x=>(string)x).SequenceEqual(new[]{"Zeta","alpha"})); });
        string[] old = new[] { "Synthetic" }, added = new[] { "NewModule" };
        Test("plan declares CREATE and UPDATE deterministically", () => { string plan=json.Serialize(Plan(old,added,old)); Check(plan.Contains("CREATE") && plan.Contains("UPDATE") && plan.IndexOf("NewModule") < plan.IndexOf("Synthetic")); });
        Test("plan rejects creation without flag", () => Reject(() => Plan(old,added,old,false), "NEW_MODULE_CREATION_NOT_ENABLED"));
        Test("creation collision never becomes an overwrite", () => Reject(() => Plan(old,added,new[]{"Synthetic","NewModule"}), "NEW_MODULE_ALREADY_EXISTS"));
        Test("case-only creation collision refused", () => Reject(() => Plan(old,added,new[]{"Synthetic","newmodule"}), "NEW_MODULE_ALREADY_EXISTS"));
        Test("unexpected TIA module cannot be deleted", () => Reject(() => Plan(old,added,new[]{"Synthetic","Foreign"}), "MODULE_SET_MISMATCH"));
        Test("missing historical module cannot be silently recreated", () => Reject(() => Plan(old,added,new string[0]), "MODULE_SET_MISMATCH"));
        Test("input case collision refused", () => Reject(() => Plan(old,new[]{"synthetic"},old), "MODULE_PLAN_NAME_COLLISION"));
        Test("live case collision refused", () => Reject(() => Plan(old,added,new[]{"Synthetic","synthetic"}), "MODULE_PLAN_NAME_COLLISION"));
        Test("module budget includes creates", () => Reject(() => Plan(old,Enumerable.Range(0,256).Select(i=>"New"+i).ToArray(),old), "MODULE_PLAN_NAME_COLLISION_OR_LIMIT"));
        Test("creation drift detected before import", () => Reject(() => Call("RecheckModuleNames",old,new[]{"Synthetic","NewModule"}), "MODULE_SET_CHANGED_BEFORE_IMPORT"));
        Test("incorrect import set rejected before save", () => Reject(() => Call("RecheckImportedModuleNames",old.Concat(added).ToArray(),old), "TIA_MODULE_SET_CHANGED_DURING_IMPORT"));
        Test("correct import set accepted independently of order", () => Call("RecheckImportedModuleNames",old.Concat(added).ToArray(),new[]{"NewModule","Synthetic"}));
        Test("incomplete creation prevents compile and save", () => {
            var calls=new List<string>();
            Action import=()=>{ calls.Add("import"); Call("RecheckImportedModuleNames",old.Concat(added).ToArray(),old); };
            Action compile=()=>calls.Add("compile"), save=()=>calls.Add("save");
            Reject(()=>Call("ExecuteImportCompileSave",import,compile,save),"TIA_MODULE_SET_CHANGED_DURING_IMPORT");
            Check(calls.SequenceEqual(new[]{"import"}));
        });
        Test("prepared create forbidden through legacy import", () => { var m=Created(PrepareCreates(CreatePackage())); Reject(() => Call("ValidatePreparedModuleAction",m,false), "FORCE_IMPORT_CREATE_INPUT_INVALID"); });
        Test("unknown prepared action refused", () => { var m=Created(PrepareCreates(CreatePackage())); m["action"]="DELETE"; Reject(() => Call("ValidatePreparedModuleAction",m,true), "FORCE_IMPORT_ACTION_INVALID"); });
        Test("fake historical baseline on create refused", () => { var m=Created(PrepareCreates(CreatePackage())); m["baseline_js_sha256"]="fake"; m["baseline_yml_sha256"]="fake"; Reject(() => Call("ValidatePreparedModuleAction",m,true), "FORCE_IMPORT_CREATE_INPUT_INVALID"); });
        Test("partial baseline on create refused", () => { var m=Created(PrepareCreates(CreatePackage())); m["baseline_js_sha256"]="fake"; Reject(() => Call("ValidatePreparedModuleAction",m,true), "FORCE_IMPORT_CREATE_INPUT_INVALID"); });
        Test("generated input cannot claim native origin", () => { var m=Created(PrepareCreates(CreatePackage())); m["input_origin"]="NATIVE"; Reject(() => Call("ValidatePreparedModuleAction",m,true), "FORCE_IMPORT_CREATE_INPUT_INVALID"); });
        Test("synthetic readback publishes new module then next cycle uses UPDATE", () => {
            string input=CreatePackage(), snapshot=Clone(input), prepared=PrepareCreates(input), readback=MultiReadback(prepared);
            Check((int)Call("FinishForceSync",readback,input,snapshot,"synthetic-lab03q",Guid.NewGuid().ToString("N"))==0);
            Call("ValidatePackage",input); Check(Directory.Exists(Path.Combine(input,"NewModule",".native")));
            var m=Created(PrepareCreates(input)); Check((string)m["action"]=="UPDATE" && m["baseline_js_sha256"]!=null);
            string second=PrepareCreates(input); Check((int)Call("FinishForceSync",MultiReadback(second),input,Clone(input),"synthetic-lab03q",Guid.NewGuid().ToString("N"))==0);
        });
        Test("new module readback tampering prevents publication", () => {
            string input=CreatePackage(), snapshot=Clone(input), readback=MultiReadback(PrepareCreates(input));
            Write(Path.Combine(readback,"NewModule",".native","NewModule.hmi.js"),"tampered");
            Check((int)Call("FinishForceSync",readback,input,snapshot,"synthetic-lab03q",Guid.NewGuid().ToString("N"))==2);
            Call("VerifyWorkspaceSnapshot",input,snapshot);
        });
        Test("local new-module edit prevents publication and survives", () => {
            string input=CreatePackage(), snapshot=Clone(input), readback=MultiReadback(PrepareCreates(input));
            Write(Path.Combine(input,"NewModule","alpha.js"),"local edit");
            Check((int)Call("FinishForceSync",readback,input,snapshot,"synthetic-lab03q",Guid.NewGuid().ToString("N"))==2);
            Check(File.ReadAllText(Path.Combine(input,"NewModule","alpha.js"))=="local edit");
        });
        int failures=results.Count(r=>json.Serialize(r).Contains("\"status\":\"FAIL\""));
        Write(Path.Combine(root,"results.json"),json.Serialize(new {status=failures==0?"PASS":"FAIL",passed=results.Count-failures,failed=failures,results,binary_sha256=Hash(args[3])}));
        Console.WriteLine("RESULTS="+Path.Combine(root,"results.json")); return failures==0?0:1;
    }
}
